module badge_access_counter (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] S,\n    input wire [2:0] D,\n    input wire [3:0] lock_count,\n    input wire [7:0] badge_max,\n    input wire [31:0] lock0,\n    input wire [31:0] lock1,\n    input wire [31:0] lock2,\n    input wire [31:0] lock3,\n    input wire [31:0] lock4,\n    input wire [31:0] lock5,\n    input wire [31:0] lock6,\n    input wire [31:0] lock7,\n    input wire [31:0] lock8,\n    input wire [31:0] lock9,\n    input wire [31:0] lock10,\n    input wire [31:0] lock11,\n    input wire [31:0] lock12,\n    input wire [31:0] lock13,\n    input wire [31:0] lock14,\n    input wire [31:0] lock15,\n    output reg [7:0] result,\n    output reg done\n);\n\n    parameter MAX_LOCKS = 16;\n    parameter MAX_ROOMS = 8;\n\n    localparam [3:0] S_IDLE = 4'd0;\n    localparam [3:0] S_PREPARE_BADGE = 4'd1;\n    localparam [3:0] S_BFS_INIT = 4'd2;\n    localparam [3:0] S_BFS_DEQUEUE = 4'd3;\n    localparam [3:0] S_BFS_CHECK_LOCK = 4'd4;\n    localparam [3:0] S_BFS_DONE = 4'd6;\n    localparam [3:0] S_INCREMENT_BADGE = 4'd7;\n    localparam [3:0] S_FINISH = 4'd8;\n\n    reg [3:0] state;\n    reg [7:0] badge_id;\n    reg [7:0] count;\n    reg [15:0] active_mask_reg;\n    reg [7:0] visited;\n    reg [2:0] queue [0:7];\n    reg [2:0] head;\n    reg [2:0] tail;\n    reg [2:0] current_u;\n    reg [3:0] lock_idx;\n    reg path_found;\n    reg [2:0] v;\n\n    wire [7:0] lock_a [0:15];\n    wire [7:0] lock_b [0:15];\n    wire [7:0] lock_x [0:15];\n    wire [7:0] lock_y [0:15];\n\n    genvar i;\n    generate\n        for (i = 0; i < 16; i = i + 1) begin : lock_assign\n            assign lock_a[i] = (i == 0) ? lock0[31:24] :\n                              (i == 1) ? lock1[31:24] :\n                              (i == 2) ? lock2[31:24] :\n                              (i == 3) ? lock3[31:24] :\n                              (i == 4) ? lock4[31:24] :\n                              (i == 5) ? lock5[31:24] :\n                              (i == 6) ? lock6[31:24] :\n                              (i == 7) ? lock7[31:24] :\n                              (i == 8) ? lock8[31:24] :\n                              (i == 9) ? lock9[31:24] :\n                              (i == 10) ? lock10[31:24] :\n                              (i == 11) ? lock11[31:24] :\n                              (i == 12) ? lock12[31:24] :\n                              (i == 13) ? lock13[31:24] :\n                              (i == 14) ? lock14[31:24] :\n                                          lock15[31:24];\n            assign lock_b[i] = (i == 0) ? lock0[23:16] :\n                              (i == 1) ? lock1[23:16] :\n                              (i == 2) ? lock2[23:16] :\n                              (i == 3) ? lock3[23:16] :\n                              (i == 4) ? lock4[23:16] :\n                              (i == 5) ? lock5[23:16] :\n                              (i == 6) ? lock6[23:16] :\n                              (i == 7) ? lock7[23:16] :\n                              (i == 8) ? lock8[23:16] :\n                              (i == 9) ? lock9[23:16] :\n                              (i == 10) ? lock10[23:16] :\n                              (i == 11) ? lock11[23:16] :\n                              (i == 12) ? lock12[23:16] :\n                              (i == 13) ? lock13[23:16] :\n                              (i == 14) ? lock14[23:16] :\n                                          lock15[23:16];\n            assign lock_x[i] = (i == 0) ? lock0[15:8] :\n                              (i == 1) ? lock1[15:8] :\n                              (i == 2) ? lock2[15:8] :\n                              (i == 3) ? lock3[15:8] :\n                              (i == 4) ? lock4[15:8] :\n                              (i == 5) ? lock5[15:8] :\n                              (i == 6) ? lock6[15:8] :\n                              (i == 7) ? lock7[15:8] :\n                              (i == 8) ? lock8[15:8] :\n                              (i == 9) ? lock9[15:8] :\n                              (i == 10) ? lock10[15:8] :\n                              (i == 11) ? lock11[15:8] :\n                              (i == 12) ? lock12[15:8] :\n                              (i == 13) ? lock13[15:8] :\n                              (i == 14) ? lock14[15:8] :\n                                          lock15[15:8];\n            assign lock_y[i] = (i == 0) ? lock0[7:0] :\n                              (i == 1) ? lock1[7:0] :\n                              (i == 2) ? lock2[7:0] :\n                              (i == 3) ? lock3[7:0] :\n                              (i == 4) ? lock4[7:0] :\n                              (i == 5) ? lock5[7:0] :\n                              (i == 6) ? lock6[7:0] :\n                              (i == 7) ? lock7[7:0] :\n                              (i == 8) ? lock8[7:0] :\n                              (i == 9) ? lock9[7:0] :\n                              (i == 10) ? lock10[7:0] :\n                              (i == 11) ? lock11[7:0] :\n                              (i == 12) ? lock12[7:0] :\n                              (i == 13) ? lock13[7:0] :\n                              (i == 14) ? lock14[7:0] :\n                                          lock15[7:0];\n        end\n    endgenerate\n\n    reg [15:0] active_mask_comb;\n    always @(*) begin\n        integer j;\n        active_mask_comb = 16'd0;\n        for (j = 0; j < MAX_LOCKS; j = j + 1) begin\n            if (j < lock_count) begin\n                if ((lock_x[j] <= (badge_id + 1)) && ((badge_id + 1) <= lock_y[j])) begin\n                    active_mask_comb[j] = 1'b1;\n                end\n            end\n        end\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            badge_id <= 8'd0;\n            count <= 8'd0;\n            active_mask_reg <= 16'd0;\n            visited <= 8'd0;\n            head <= 3'd0;\n            tail <= 3'd0;\n            current_u <= 3'd0;\n            lock_idx <= 4'd0;\n            path_found <= 1'b0;\n            v <= 3'd0;\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    if (start) begin\n                        badge_id <= 8'd0;\n                        count <= 8'd0;\n                        state <= S_PREPARE_BADGE;\n                        done <= 1'b0;\n                    end\n                end\n                S_PREPARE_BADGE: begin\n                    active_mask_reg <= active_mask_comb;\n                    state <= S_BFS_INIT;\n                end\n                S_BFS_INIT: begin\n                    visited <= 8'd0;\n                    head <= 3'd0;\n                    tail <= 3'd0;\n                    queue[0] <= S;\n                    tail <= 3'd1;\n                    visited[S] <= 1'b1;\n                    path_found <= 1'b0;\n                    lock_idx <= 4'd0;\n                    state <= S_BFS_DEQUEUE;\n                end\n                S_BFS_DEQUEUE: begin\n                    if (head != tail) begin\n                        current_u <= queue[head];\n                        head <= head + 3'd1;\n                        lock_idx <= 4'd0;\n                        state <= S_BFS_CHECK_LOCK;\n                    end else begin\n                        state <= S_BFS_DONE;\n                    end\n                end\n                S_BFS_CHECK_LOCK: begin\n                    if (current_u == D) begin\n                        path_found <= 1'b1;\n                        state <= S_BFS_DONE;\n                    end else if (lock_idx < lock_count) begin\n                        if (active_mask_reg[lock_idx] && (lock_a[lock_idx] == current_u)) begin\n                            v <= lock_b[lock_idx];\n                            if (!visited[lock_b[lock_idx]]) begin\n                                queue[tail] <= lock_b[lock_idx];\n                                tail <= tail + 3'd1;\n                                visited[lock_b[lock_idx]] <= 1'b1;\n                            end\n                        end\n                        lock_idx <= lock_idx + 4'd1;\n                        state <= S_BFS_CHECK_LOCK;\n                    end else begin\n                        state <= S_BFS_DEQUEUE;\n                    end\n                end\n                S_BFS_DONE: begin\n                    if (path_found) begin\n                        count <= count + 8'd1;\n                    end\n                    state <= S_INCREMENT_BADGE;\n                end\n                S_INCREMENT_BADGE: begin\n                    if (badge_id + 8'd1 < badge_max) begin\n                        badge_id <= badge_id + 8'd1;\n                        state <= S_PREPARE_BADGE;\n                    end else begin\n                        state <= S_FINISH;\n                    end\n                end\n                S_FINISH: begin\n                    result <= count;\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= S_IDLE;\n                        done <= 1'b0;\n                    end\n                end\n                default: state <= S_IDLE;\n            endcase\n        end\n    end\nendmodule